pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(putAmount < 1e77); // avoid overflow in balance addition
        vm.assume(collectAmount < 1e77);
        vm.assume(sender != address(0));
        vm.assume(unlockTime <= block.timestamp + 1000000); // keep reasonable

        // Fund sender and call Put
        vm.deal(sender, putAmount);
        vm.prank(sender);
        c.Put{value: putAmount}(unlockTime);

        // Now warp time if needed to make unlock time pass
        uint256 minUnlock = c.Acc(sender).unlockTime;
        if (block.timestamp <= minUnlock) {
            vm.warp(minUnlock + 1);
        }

        // Record balance before Collect
        uint256 balBefore = address(c).balance;
        uint256 accBalanceBefore = c.Acc(sender).balance;

        // Attempt Collect
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success && accBalanceBefore >= c.MinSum() && accBalanceBefore >= collectAmount && collectAmount > 0) {
            // If Collect succeeded, contract balance should have decreased by at least collectAmount
            uint256 balAfter = address(c).balance;
            assertTrue(balAfter <= balBefore - collectAmount, "Contract balance should decrease by at least collectAmount");
        } else {
            // Otherwise, no assertion needed; skip
            assertTrue(true);
        }
    }
}

