pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller1, uint256 putAmount1, uint256 putUnlock, uint256 collectAmount) public {
        vm.assume(caller1 != address(0));
        putAmount1 = bound(putAmount1, 0, 100 ether);
        putUnlock = bound(putUnlock, 0, 100 days);
        collectAmount = bound(collectAmount, 0, putAmount1);

        // Execute Put for caller1
        vm.deal(caller1, putAmount1);
        vm.prank(caller1);
        c.Put{value: putAmount1}(putUnlock);

        // Set block.timestamp past unlock time
        vm.warp(block.timestamp + 101 days);

        // Compute expected sum of all Acc balances before Collect
        uint256 sumBefore = 0;
        (uint256 unlockTime1, uint256 balance1) = c.Acc(caller1);
        sumBefore += balance1;

        // Call Collect
        vm.prank(caller1);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        if (!success) return;

        // Compute sum after Collect
        uint256 sumAfter = 0;
        (unlockTime1, balance1) = c.Acc(caller1);
        sumAfter += balance1;

        // Rule: sum of all user balances equals contract balance
        assertTrue(sumAfter == address(c).balance, "Sum of Acc balances != contract balance");
    }
}

