pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 deposit, uint256 unlockTime, uint256 withdrawAmount) public {
        // Bound inputs to avoid overflows and unrealistic values
        vm.assume(caller != address(0));
        vm.assume(deposit > 0 && deposit <= 1e30);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= deposit);

        // Set up by calling Put via fallback or direct call
        vm.deal(caller, deposit + 1 ether); // ensure caller has enough ETH
        vm.prank(caller);
        (bool putSuccess,) = address(c).call{value: deposit}(""); // fallback calls Put(0)
        require(putSuccess);

        // Fast-forward time past any unlock
        uint256 targetUnlock = block.timestamp + unlockTime % 365 days;
        vm.warp(targetUnlock + 1); // ensure unlockTime passed

        // Record balance before Collect
        (uint256 prevUnlockTime, uint256 prevBalance) = c.Acc(caller);

        // Call Collect
        vm.prank(caller);
        (bool collectSuccess,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // If Collect succeeded, the caller's balance should have decreased by exactly withdrawAmount
        // In the correct contract this holds; in the buggy one, balance stays same
        if (collectSuccess) {
            (uint256 newUnlockTime, uint256 newBalance) = c.Acc(caller);
            assertTrue(newBalance == prevBalance - withdrawAmount, "Balance should decrease by withdraw amount");
        }
    }
}

