pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 am) public {
        // Ensure the user has at least 1 ether (MinSum) for Collect to potentially succeed
        vm.assume(am >= 1 ether);
        vm.deal(user, am);

        // Pre-state: deposit exactly am into the contract via fallback (calls Put(0))
        vm.prank(user);
        (bool putSuccess,) = address(c).call{value: am}("");
        require(putSuccess, "Put failed");

        // Record the user's balance before Collect
        uint256 balanceBefore = c.Acc(user).balance;

        // Attempt Collect with amount am (which should succeed if conditions met)
        vm.prank(user);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        // The rule: if Collect did not revert, the user's balance in the mapping must be unchanged
        if (success) {
            uint256 balanceAfter = c.Acc(user).balance;
            assertTrue(balanceAfter == balanceBefore, "Balance should not change when Collect succeeds");
        }
    }
}

