pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        putAmount = bound(putAmount, 0, 1_000_000 ether);
        collectAmount = bound(collectAmount, 0, 1_001_000 ether);
        if (putAmount < 1 ether) vm.assume(putAmount >= 1 ether);

        // Set up: send ether so caller has balance
        vm.deal(address(this), putAmount);
        c.Put{value: putAmount}(unlockTime);

        // Warp to past unlock time so Collect can succeed
        if (block.timestamp <= c.Acc(address(this)).unlockTime()) {
            vm.warp(c.Acc(address(this)).unlockTime() + 1);
        }

        uint256 balanceBefore = c.Acc(address(this)).balance();
        bool reverted = false;
        try c.Collect(collectAmount) {
            uint256 balanceAfter = c.Acc(address(this)).balance();
            // When Collect succeeds, the balance must decrease by exactly collectAmount
            assertTrue(balanceAfter == balanceBefore - collectAmount);
        } catch {
            reverted = true;
            // When Collect reverts, balance must stay unchanged
            uint256 balanceAfter = c.Acc(address(this)).balance();
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

